def route(task):
    if task.has_ambiguous_requirements or task.high_cost_to_reverse:
        return "claude-opus-5"
    if task.is_bounded and task.has_automated_validation:
        return "claude-sonnet-5"
    return "claude-sonnet-5"  # escalate if validation or confidence checks fail

def build_request(model, task, profile):
    request = {"model": model, "messages": task.messages}
    if profile.supports_sampling_settings:
        request.update(task.approved_sampling_settings)
    # Parse and validate returned tool arguments against the application schema.
    return request
